import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import Swal from "sweetalert2";

export default function ParentFeePage({ admissionNoFromParams }) {
  const admissionNo = admissionNoFromParams || ""; // assume route param or input
  const [summary, setSummary] = useState(null);
  const [amount, setAmount] = useState("");

  useEffect(() => {
    if (!admissionNo) return;
    axios.get(`http://localhost:5000/api/fees/student/${admissionNo}`)
      console.log("Fetching fees from:", `http://localhost:5000/api/fees/student/${admissionNo}`)

      .then(res => {
        if (res.data.success) setSummary(res.data.data);
      })
      .catch(err => { console.error(err); toast.error("Failed to load");});
  }, [admissionNo]);

  const payNow = async () => {
    const amt = Number(amount);
    if (!amt || amt <= 0) return toast.error("Enter valid amount");
    // Optional: confirm via Swal
    const ok = await Swal.fire({
      title: `Pay ₹${amt}?`,
      text: "Proceed to simulated payment",
      showCancelButton: true
    });
    if (!ok.isConfirmed) return;

    try {
      const res = await axios.post("/api/fees/pay", { admissionNo, amount: amt, method: "simulated" });
      if (res.data.success) {
        toast.success("Payment successful");
        // reload summary
        const s = await axios.get(`/api/fees/student/${admissionNo}`);
        if (s.data.success) setSummary(s.data.data);
      } else {
        toast.error(res.data.error || "Payment failed");
      }
    } catch (err) {
      console.error(err);
      toast.error("Payment failed");
    }
  };

  if (!summary) return <p>Loading...</p>;

  const { student, fee, payments } = summary;

  return (
    <div>
      <Toaster />
      <h2>Fee Summary for {student.name} ({student.admissionNo})</h2>
      <h3>Total: ₹{fee.total}</h3>
      <h4>Paid: ₹{fee.paid}</h4>
      <h4>Remaining: ₹{fee.remaining}</h4>

      <h4>Breakdown</h4>
      <ul>
        {Object.entries(fee.items).map(([k, v]) => (
          <li key={k}>{v.title}: ₹{v.amount}</li>
        ))}
      </ul>

      <div>
        <input value={amount} onChange={e => setAmount(e.target.value)} placeholder="Enter amount to pay" />
        <button onClick={payNow}>Pay</button>
        <button onClick={() => { setAmount(fee.remaining); }}>Pay Full</button>
      </div>

      <h4>Transactions</h4>
      <ul>
        {payments.map(p => (
          <li key={p._id}>₹{p.amount} — {new Date(p.createdAt).toLocaleString()} — {p.paymentMethod}</li>
        ))}
      </ul>
    </div>
  );
}
